static RadixUserData *AllocUserData(uint8_t netmask, void *user)
{
    RadixUserData *user_data = SCCalloc(1, sizeof(RadixUserData));
    if (unlikely(user_data == NULL)) {
        sc_errno = SC_ENOMEM;
        return NULL;
    }
    user_data->netmask = netmask;
    user_data->user = user;
    return user_data;
}

/**
