class RadixTree(object):
    """Generic port of the radix tree shared by util-radix{4,6}-tree.c."""

    def __init__(self, address_bytes, netmask_max):
        self.address_bytes = address_bytes
        self.netmask_max = netmask_max
        self.head = None
        self.errno = SC_OK

    # -- user data list helpers ------------------------------------------
    @staticmethod
    def _append_user_data(node, netmask, user):
        """AppendToUserDataList(): descending order on netmask."""
        pos = len(node.user_data)
        for idx, (existing_netmask, _user) in enumerate(node.user_data):
            if netmask > existing_netmask:
                pos = idx
                break
        node.user_data.insert(pos, (netmask, user))

    @staticmethod
    def _contain_netmask(node, netmask):
        """ContainNetmask()."""
        return any(nm == netmask for nm, _u in node.user_data)

    @staticmethod
    def _contain_netmask_and_get_user(node, netmask, exact_match):
        """ContainNetmaskAndSetUserData(); returns (found, user)."""
        if exact_match:
            # only looks at the head of the list
            if node.user_data and node.user_data[0][0] == netmask:
                return True, node.user_data[0][1]
            return False, None
        for nm, user in node.user_data:
            if nm == netmask:
                return True, user
        return False, None

    def _process_internode(self, node, inter_node):
        """ProcessInternode(): split masks between node and inter_node."""
        differ_bit = inter_node.bit
        rem = set()
        for x in range(self.netmask_max + 1):
            m = self.netmask_max - x
            if m == differ_bit:
                break
            if m in node.masks:
                rem.add(m)
        inter_node.masks |= node.masks
        inter_node.masks -= rem
        node.masks = rem

    # -- AddKey ----------------------------------------------------------
    def add_key(self, key_stream, netmask, user, exclusive):
        """AddKey(). Returns the node, or None with self.errno set."""
        netmask_max = self.netmask_max
        tmp_stream = bytearray(key_stream)
        mask_ip_netblock(tmp_stream, netmask, netmask_max)

        if self.head is None:
            node = RadixNode(netmask_max)
            node.prefix_stream = bytes(tmp_stream)
            node.has_prefix = True
            node.user_data = [(netmask, user)]
            self.head = node
            if netmask == netmask_max:
                return node
            node.masks.add(netmask)
            return node

        node = self.head

        # walk down to a node that ends in a prefix
        while node.bit < netmask_max or not node.has_prefix:
            if netmask_max <= node.bit:
                if node.right is None:
                    break
                node = node.right
            else:
                if _bittest(tmp_stream[node.bit >> 3], 0x80 >> (node.bit % 8)):
                    if node.right is None:
                        break
                    node = node.right
                else:
                    if node.left is None:
                        break
                    node = node.left

        bottom_node = node

        # first bit position where the ips differ
        check_bit = min(node.bit, netmask_max)
        differ_bit = 0
        j = 0
        i = 0
        while (i * 8) < check_bit:
            temp = tmp_stream[i] ^ bottom_node.prefix_stream[i]
            if temp == 0:
                differ_bit = (i + 1) * 8
                i += 1
                continue
            temp = temp * 2
            if temp >= 256:
                j = 0
            elif temp >= 128:
                j = 1
            elif temp >= 64:
                j = 2
            elif temp >= 32:
                j = 3
            elif temp >= 16:
                j = 4
            elif temp >= 8:
                j = 5
            elif temp >= 4:
                j = 6
            elif temp >= 2:
                j = 7
            differ_bit = i * 8 + j
            break
        if check_bit < differ_bit:
            differ_bit = check_bit

        # walk up the tree to the insert position
        parent = node.parent
        while parent is not None and differ_bit <= parent.bit:
            node = parent
            parent = node.parent

        if differ_bit == netmask_max and node.bit == netmask_max:
            if node.has_prefix:
                if self._contain_netmask(node, netmask):
                    # perfect duplicate
                    if exclusive:
                        self.errno = SC_EEXIST
                        return None
                else:
                    self._append_user_data(node, netmask, user)
                    if netmask == netmask_max:
                        return node
                    parent = node.parent
                    while parent is not None and netmask < (parent.bit + 1):
                        node = parent
                        parent = parent.parent
                    node.masks.add(netmask)
                    if node.masks == {netmask}:
                        return node
            return node

        # new leaf node
        new_node = RadixNode(netmask_max)
        new_node.prefix_stream = bytes(tmp_stream)
        new_node.has_prefix = True
        new_node.user_data = [(netmask, user)]

        inter_node = RadixNode(netmask_max)
        inter_node.has_prefix = False
        inter_node.bit = differ_bit
        inter_node.parent = node.parent

        self._process_internode(node, inter_node)

        if _bittest(tmp_stream[differ_bit >> 3], 0x80 >> (differ_bit % 8)):
            inter_node.left = node
            inter_node.right = new_node
        else:
            inter_node.left = new_node
            inter_node.right = node
        new_node.parent = inter_node

        if node.parent is None:
            self.head = inter_node
        elif node.parent.right is node:
            node.parent.right = inter_node
        else:
            node.parent.left = inter_node

        node.parent = inter_node

        if netmask != netmask_max:
            node = new_node
            parent = new_node.parent
            while parent is not None and netmask < (parent.bit + 1):
                node = parent
                parent = parent.parent
            node.masks.add(netmask)
        return new_node

    # -- FindBestMatch ---------------------------------------------------
    def find_best_match(self, key_stream):
        """FindBestMatch(); returns the user data or None."""
        found, user = self._find_key(key_stream, self.netmask_max, False)
        return user if found else None

    def _find_key(self, key_stream, netmask, exact_match):
        """FindKey(); returns (found, user)."""
        netmask_max = self.netmask_max
        if self.head is None:
            return False, None

        node = self.head
        tmp_stream = bytearray(key_stream)

        while node.bit < netmask_max:
            if _bittest(tmp_stream[node.bit >> 3], 0x80 >> (node.bit % 8)):
                node = node.right
            else:
                node = node.left
            if node is None:
                return False, None

        if node.bit != netmask_max or not node.has_prefix:
            return False, None

        if node.prefix_stream == bytes(tmp_stream):
            found, user = self._contain_netmask_and_get_user(node, netmask, True)
            if found:
                return True, user

        if exact_match:
            return False, None

        return self._find_key_ip_netblock(tmp_stream, node)

    def _find_key_ip_netblock(self, key_stream, node):
        """FindKeyIPNetblock(); returns (found, user)."""
        netmask_max = self.netmask_max

        while node is not None and not node.masks:
            node = node.parent
        if node is None:
            return False, None

        tmp_stream = bytearray(key_stream)
        netmask_node = node

        for jj in range(netmask_max + 1):
            m = netmask_max - jj

            if m not in netmask_node.masks:
                continue

            mask_ip_netblock(tmp_stream, m, netmask_max)

            while node.bit < netmask_max:
                if _bittest(tmp_stream[node.bit >> 3], 0x80 >> (node.bit % 8)):
                    node = node.right
                else:
                    node = node.left
                if node is None:
                    return False, None

            if node.bit != netmask_max or not node.has_prefix:
                return False, None

            if node.prefix_stream == bytes(tmp_stream):
                found, user = self._contain_netmask_and_get_user(node, m, False)
                if found:
                    return True, user

        return self._find_key_ip_netblock(tmp_stream, netmask_node.parent)

    # -- string add helpers ----------------------------------------------
    def add_key_ipv4_string(self, text, user):
        """SCRadix4AddKeyIPV4String()."""
        # strlcpy(ip_str, str, sizeof(ip_str) - 2) with ip_str[32]
        ip_str = text[:29]
        netmask = 32
        if "/" in ip_str:
            ip_str, mask_str = ip_str.split("/", 1)
            if "." in mask_str:
                self.errno = SC_EINVAL
                return False
            if not _parse_u8_range(mask_str, 0, 32):
                self.errno = SC_EINVAL
                return False
            netmask = int(mask_str)
        try:
            addr = socket.inet_pton(socket.AF_INET, ip_str)
        except (OSError, UnicodeEncodeError):
            self.errno = SC_EINVAL
            return False
        self.errno = SC_OK
        return self.add_key(addr, netmask, user, True) is not None

    def add_key_ipv6_string(self, text, user):
        """SCRadix6AddKeyIPV6String()."""
        ip_str = text[:79]
        netmask = 128
        if "/" in ip_str:
            ip_str, mask_str = ip_str.split("/", 1)
            if "." in mask_str:
                self.errno = SC_EINVAL
                return False
            if not _parse_u8_range(mask_str, 0, 128):
                self.errno = SC_EINVAL
                return False
            netmask = int(mask_str)
        try:
            addr = socket.inet_pton(socket.AF_INET6, ip_str)
        except (OSError, UnicodeEncodeError):
            self.errno = SC_EINVAL
            return False
        self.errno = SC_OK
        return self.add_key(addr, netmask, user, True) is not None


def _parse_u8_range(text, low, high):
    """StringParseU8RangeCheck() with base 10 and strict parsing."""
    if not text or not text.isdigit() or not text.isascii():
        return False
    value = int(text)
    return value <= 0xFF and low <= value <= high

