class HostOSInfo(object):
    def __init__(self):
        self.tree4 = RadixTree(4, 32)
        self.tree6 = RadixTree(16, 128)

    def add_host_os_info(self, host_os, host_os_ip_range, is_ipv4):
        """SCHInfoAddHostOSInfo(): policy value on success, -1 on failure."""
        if host_os is None or host_os_ip_range is None or len(host_os_ip_range) == 0:
            return -1

        user_data = map_enum_name_to_value(host_os)
        if user_data == -1:
            return -1

        if host_os_ip_range.lower() == "default":
            host_os_ip_range = "0.0.0.0/0" if is_ipv4 else "::/0"

        ip_str = host_os_ip_range
        ip_str_rem = None
        if "," in ip_str:
            ip_str, ip_str_rem = ip_str.split(",", 1)

        if ":" not in ip_str:
            if not self.tree4.add_key_ipv4_string(ip_str, user_data):
                raise HostOSError(self.tree4.errno, ip_str)
        else:
            if not self.tree6.add_key_ipv6_string(ip_str, user_data):
                raise HostOSError(self.tree6.errno, ip_str)

        if ip_str_rem is not None:
            self.add_host_os_info(host_os, ip_str_rem, is_ipv4)

        return user_data

    def get_host_os_flavour(self, text):
        """SCHInfoGetHostOSFlavour(): policy value, or -1 when not found."""
        if text is None or "/" in text:
            return -1
        if ":" in text:
            try:
                addr = socket.inet_pton(socket.AF_INET6, text)
            except (OSError, UnicodeEncodeError):
                return -1
            user_data = self.tree6.find_best_match(addr)
        else:
            try:
                addr = socket.inet_pton(socket.AF_INET, text)
            except (OSError, UnicodeEncodeError):
                return -1
            user_data = self.tree4.find_best_match(addr)
        return -1 if user_data is None else user_data

    def load_from_config(self, policies):
        """SCHInfoLoadFromConfig() over an ordered (name, [hosts]) list.

        Unlike the engine -- which aborts on any failure -- invalid flavour
        keys are simply skipped here, per the tool's contract.
        """
        for name, hosts in policies:
            # conf-yaml-loader Mangle(): '_' becomes '-' in key names.
            policy_name = name.replace("_", "-") if "_" in name else name
            if map_enum_name_to_value(policy_name) == -1:
                continue
            for host in hosts:
                if host is None:
                    continue
                is_ipv4 = 0 if ":" in host else 1
                if self.add_host_os_info(policy_name, host, is_ipv4) == -1:
                    raise HostOSError(SC_EINVAL, host)


class HostOSError(Exception):
    def __init__(self, errno, addr):
        Exception.__init__(self, "%s: %d" % (addr, errno))
        self.errno = errno
        self.addr = addr


# ---------------------------------------------------------------------------
# YAML input
# ---------------------------------------------------------------------------


def parse_policy_yaml(path):
    """Read the policy document as an ordered list of (flavour, [hosts]).

    Root keys are flavour names; a 'host-os-policy' root key is also accepted
    so that a suricata.yaml-style block loads too.
    """
    with open(path, "r") as fh:
        text = fh.read()

    mapping = _load_yaml_mapping(text)
    if len(mapping) == 1 and mapping[0][0] == "host-os-policy":
        inner = mapping[0][1]
        mapping = inner if isinstance(inner, list) else []

    policies = []
    for key, value in mapping:
        if value is None:
            hosts = []
        elif isinstance(value, list):
            hosts = [v for v in value if isinstance(v, str)]
        elif isinstance(value, str):
            hosts = [value]
        else:
            hosts = []
        policies.append((key, hosts))
    return policies


def _load_yaml_mapping(text):
    """Return the root mapping as a list of (key, value) pairs.

    Uses PyYAML when available, otherwise a small parser for the
    'key: [a, b]' / 'key:' + '- a' subset these documents use.
    """
    try:
        import yaml
    except ImportError:
        return _load_yaml_mapping_fallback(text)

    data = yaml.safe_load(text)
    if not isinstance(data, dict):
        return []
    out = []
    for key, value in data.items():
        if not isinstance(key, str):
            continue
        if isinstance(value, dict):
            value = [(k, v) for k, v in value.items() if isinstance(k, str)]
        out.append((key, value))
    return out


def _load_yaml_mapping_fallback(text):
    pairs = []
    current = None
    for raw in text.splitlines():
        line = raw.split("#", 1)[0].rstrip() if not raw.lstrip().startswith("#") else ""
        if not line.strip() or line.strip() in ("---", "...") or line.startswith("%"):
            continue
        stripped = line.strip()
        if stripped.startswith("- "):
            if current is not None:
                current[1].append(stripped[2:].strip().strip("'\""))
            continue
        if ":" not in stripped:
            continue
        key, _sep, value = stripped.partition(":")
        key = key.strip().strip("'\"")
        value = value.strip()
        if value.startswith("[") and value.endswith("]"):
            items = [v.strip().strip("'\"") for v in value[1:-1].split(",")]
            pairs.append((key, [v for v in items if v]))
            current = None
        elif value:
            pairs.append((key, [value.strip("'\"")]))
            current = None
        else:
            current = (key, [])
            pairs.append(current)
    return [(k, list(v)) for k, v in pairs]


