USAGE = """usage:
  ospolicy cidr ipv4-mask <dotted-quad>
  ospolicy cidr ipv4-prefix <n>
  ospolicy cidr ipv6-prefix <n>
  ospolicy load <yaml-path>   (IPs on stdin, one per line)
"""


def cmd_cidr(args):
    if len(args) != 2:
        sys.stderr.write(USAGE)
        return 2
    what, value = args

    if what == "ipv4-mask":
        try:
            netmask = dotted_quad_to_nbo_u32(value)
        except (OSError, UnicodeEncodeError):
            sys.stderr.write("invalid netmask\n")
            return 1
        sys.stdout.write("%d\n" % cidr_from_mask(netmask))
        return 0

    if what in ("ipv4-prefix", "ipv6-prefix"):
        try:
            cidr = int(value, 10)
        except ValueError:
            sys.stderr.write("invalid cidr\n")
            return 1
        if what == "ipv4-prefix":
            sys.stdout.write("%08x\n" % cidr_get(cidr))
        else:
            sys.stdout.write("%s\n" % cidr_get_ipv6(cidr).hex())
        return 0

    sys.stderr.write(USAGE)
    return 2


def cmd_load(args):
    if len(args) != 1:
        sys.stderr.write(USAGE)
        return 2

    hinfo = HostOSInfo()
    try:
        policies = parse_policy_yaml(args[0])
    except OSError as err:
        sys.stderr.write("%s\n" % err)
        return 1

    try:
        hinfo.load_from_config(policies)
    except HostOSError as err:
        if err.errno == SC_EEXIST:
            sys.stderr.write("duplicate\n")
        else:
            sys.stderr.write("invalid address '%s'\n" % err.addr)
        return 1

    out = []
    for line in sys.stdin:
        ip = line.strip()
        if not ip:
            continue
        value = hinfo.get_host_os_flavour(ip)
        flavour = "none" if value == -1 else map_enum_value_to_name(value)
        out.append("%s %s\n" % (ip, flavour))
    sys.stdout.write("".join(out))
    return 0


def main(argv):
    if len(argv) < 2:
        sys.stderr.write(USAGE)
        return 2
    cmd = argv[1]
    if cmd == "cidr":
        return cmd_cidr(argv[2:])
    if cmd == "load":
        return cmd_load(argv[2:])
    if cmd == "selftest":
        return selftest()
    sys.stderr.write(USAGE)
    return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv))

