/* Verbatim copies of the three functions from /app/src/util-cidr.c, so the
 * real ntohl/htonl and struct layouts decide the answers. */
#include <arpa/inet.h>
#include <netinet/in.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

int CIDRFromMask(uint32_t netmask)
{
    netmask = ntohl(netmask);
    if (netmask == 0) {
        return 0;
    }
    int p = 0;
    bool seen_1 = false;
    while (netmask > 0) {
        if (netmask & 1) {
            seen_1 = true;
            p++;
        } else {
            if (seen_1) {
                return -1;
            }
        }
        netmask >>= 1;
    }
    return p;
}

uint32_t CIDRGet(int cidr)
{
    if (cidr <= 0 || cidr > 32)
        return 0;
    uint32_t netmask = htonl(0xFFFFFFFF << (32UL - (uint32_t)cidr));
    return netmask;
}

void CIDRGetIPv6(int cidr, struct in6_addr *in6)
{
    int i = 0;

    memset(in6, 0, sizeof(struct in6_addr));

    while (cidr > 8) {
        in6->s6_addr[i] = 0xff;
        cidr -= 8;
        i++;
    }

    while (cidr > 0) {
        in6->s6_addr[i] |= 0x80;
        if (--cidr > 0)
            in6->s6_addr[i] = in6->s6_addr[i] >> 1;
    }
}

static void mask(const char *q)
{
    struct in_addr in;
    if (inet_pton(AF_INET, q, &in) <= 0) {
        printf("mask %s invalid\n", q);
        return;
    }
    printf("mask %s %d\n", q, CIDRFromMask(in.s_addr));
}

static void v6(int cidr)
{
    struct in6_addr in6;
    CIDRGetIPv6(cidr, &in6);
    printf("v6 %d ", cidr);
    for (int i = 0; i < 16; i++)
        printf("%02x", in6.s6_addr[i]);
    printf("\n");
}

int main(void)
{
    mask("255.255.255.0");
    mask("255.255.0.42");
    mask("0.0.0.0");
    mask("255.255.255.255");
    mask("128.0.0.0");
    mask("255.254.0.0");
    mask("0.255.255.255");
    for (int c = -1; c <= 33; c++)
        printf("get %d %08x\n", c, CIDRGet(c));
    for (int c = 0; c <= 128; c++)
        v6(c);
    return 0;
}

