        in6->s6_addr[i] |= 0x80;
        if (--cidr > 0)
            in6->s6_addr[i] = in6->s6_addr[i] >> 1;
    }
}

/* StringParseU8RangeCheck(): base-10, strict (see /app/src/util-byte.c) */
static inline int StringParseU8RangeCheck(
        uint8_t *res, int base, size_t len, const char *str, uint8_t min, uint8_t max)
{
    const char *ptr = str;
    char *endptr = NULL;

    while (isspace((unsigned char)*ptr))
        ptr++;
    if (*ptr == '-')
        return -1;
    if (!isdigit((unsigned char)*ptr))
        return -1;

    errno = 0;
    uint64_t u64 = strtoull(ptr, &endptr, base);
    if (endptr == ptr)
        return -1;
    if (errno == ERANGE)
        return -1;
    /* strict: nothing but the number */
    if (*endptr != '\0')
        return -1;
    if (u64 > UINT8_MAX)
        return -1;
    *res = (uint8_t)u64;
    if (*res < min || *res > max)
        return -1;
    return (int)(endptr - str);
}

