/* Drives the REAL Suricata radix trees exactly as util-host-os-info.c does,
 * so /results/ospolicy can be differentially tested against them.
 *
 * stdin protocol:
 *   4 <flavour-int> <ip-or-netblock>   -> add to the ipv4 tree
 *   6 <flavour-int> <ip-or-netblock>   -> add to the ipv6 tree
 *   ? <ip>                             -> best-match lookup, prints flavour
 * Output: "add <rc>" / "get <flavour>"  (rc: 0 ok, -1 invalid, -2 duplicate)
 */
#include "suricata-common.h"
#include "util-radix4-tree.h"
#include "util-radix6-tree.h"

__thread SCError sc_errno = SC_OK;

static void FreeUD(void *data)
{
    if (data != NULL)
        SCFree(data);
}

static const SCRadix4Config cfg4 = { FreeUD, NULL };
static const SCRadix6Config cfg6 = { FreeUD, NULL };

static SCRadix4Tree tree4 = SC_RADIX4_TREE_INITIALIZER;
static SCRadix6Tree tree6 = SC_RADIX6_TREE_INITIALIZER;

static int *MkUD(int v)
{
    int *ud = SCMalloc(sizeof(int));
    *ud = v;
    return ud;
}

int main(void)
{
    char line[256];

    while (fgets(line, sizeof(line), stdin) != NULL) {
        size_t n = strlen(line);
        while (n > 0 && (line[n - 1] == '\n' || line[n - 1] == '\r'))
            line[--n] = '\0';
        if (n == 0)
            continue;

        char kind = line[0];
        char *rest = line + 1;
        while (*rest == ' ')
            rest++;

        if (kind == '4' || kind == '6') {
            int flavour = (int)strtol(rest, &rest, 10);
            while (*rest == ' ')
                rest++;
            sc_errno = SC_OK;
            int *ud = MkUD(flavour);
            bool ok;
            if (kind == '4')
                ok = SCRadix4AddKeyIPV4String(&tree4, &cfg4, rest, ud);
            else
                ok = SCRadix6AddKeyIPV6String(&tree6, &cfg6, rest, ud);
            if (!ok) {
                int rc = (sc_errno == SC_EEXIST) ? -2 : -1;
                FreeUD(ud);
                printf("add %d\n", rc);
            } else {
                printf("add 0\n");
            }
        } else if (kind == '?') {
            void *user_data = NULL;
