#!/usr/bin/env python3
"""Differential test: /results/ospolicy's radix port vs the real C radix trees.

Generates random clustered add/lookup workloads, replays them through both the
compiled Suricata tree code (/tmp/rx/driver) and the Python port, and compares
every single answer.
"""
import importlib.util
import random
import socket
import subprocess
import sys

spec = importlib.util.spec_from_loader(
    "ospolicy",
    importlib.machinery.SourceFileLoader("ospolicy", "/results/ospolicy"),
)
osp = importlib.util.module_from_spec(spec)
spec.loader.exec_module(osp)

DRIVER = "/tmp/rx/driver"


def rand_v4(rng):
    """Clustered so netblocks overlap heavily."""
    style = rng.randrange(4)
    if style == 0:
        return "10.%d.%d.%d" % (rng.randrange(3), rng.randrange(4), rng.randrange(8))
    if style == 1:
        return "192.168.%d.%d" % (rng.randrange(3), rng.choice([0, 1, 100, 128, 200, 255]))
    if style == 2:
        return "111.162.%d.%d" % (rng.choice([194, 208, 214, 240]), rng.randrange(256))
    return "%d.%d.%d.%d" % tuple(rng.randrange(256) for _ in range(4))


def rand_v6(rng):
    style = rng.randrange(3)
    if style == 0:
        return "2001:db8:%x::%x" % (rng.randrange(4), rng.randrange(8))
    if style == 1:
        return "8762:2352:6241:7245:EE23:21AD:%04X:%04X" % (
            rng.choice([0x2312, 0x2412, 0x2121, 0xFFFF]), rng.randrange(0x10000))
    return ":".join("%x" % rng.randrange(0x10000) for _ in range(8))


def gen_case(rng):
    """Returns (ops, lookups) where ops are (family, flavour, text)."""
    ops = []
    n_add = rng.randrange(1, 14)
    for _ in range(n_add):
        flavour = rng.randrange(1, 15)
        if rng.random() < 0.65:
            addr = rand_v4(rng)
            if rng.random() < 0.6:
                addr = "%s/%d" % (addr, rng.choice([0, 1, 8, 12, 16, 20, 24, 25, 28, 31, 32]))
            ops.append(("4", flavour, addr))
        else:
            addr = rand_v6(rng)
            if rng.random() < 0.6:
                addr = "%s/%d" % (addr, rng.choice([0, 1, 16, 32, 48, 64, 68, 96, 120, 127, 128]))
            ops.append(("6", flavour, addr))

    lookups = []
    for _ in range(12):
        lookups.append(rand_v4(rng) if rng.random() < 0.6 else rand_v6(rng))
    # also look up the exact and near-miss forms of what we added
    for fam, _f, text in ops:
        base = text.split("/")[0]
        lookups.append(base)
    return ops, lookups


def run_c(ops, lookups):
    lines = ["%s %d %s" % (fam, flav, text) for fam, flav, text in ops]
    lines += ["? %s" % ip for ip in lookups]
    out = subprocess.run([DRIVER], input="\n".join(lines) + "\n",
                         capture_output=True, text=True, check=True).stdout
    return out.strip().split("\n")


def run_py(ops, lookups):
    h = osp.HostOSInfo()
    res = []
    for fam, flav, text in ops:
        if fam == "4":
            ok = h.tree4.add_key_ipv4_string(text, flav)
            errno = h.tree4.errno
        else:
            ok = h.tree6.add_key_ipv6_string(text, flav)
            errno = h.tree6.errno
        if ok:
            res.append("add 0")
        else:
            res.append("add %d" % (-2 if errno == osp.SC_EEXIST else -1))
    for ip in lookups:
        res.append("get %d" % h.get_host_os_flavour(ip))
    return res


def main():
    iterations = int(sys.argv[1]) if len(sys.argv) > 1 else 300
    seed0 = int(sys.argv[2]) if len(sys.argv) > 2 else 0
    mismatches = 0
    total_answers = 0

    for it in range(iterations):
        rng = random.Random(seed0 + it)
        ops, lookups = gen_case(rng)
        c_out = run_c(ops, lookups)
        py_out = run_py(ops, lookups)
        total_answers += len(py_out)
        if c_out != py_out:
            mismatches += 1
            if mismatches <= 3:
                print("MISMATCH seed=%d" % (seed0 + it))
                for fam, flav, text in ops:
                    print("  add %s %d %s" % (fam, flav, text))
                for i, (c, p) in enumerate(zip(c_out, py_out)):
                    if c != p:
                        label = lookups[i - len(ops)] if i >= len(ops) else ops[i][2]
                        print("  [%d] %-24s C=%s PY=%s" % (i, label, c, p))

    print("iterations=%d answers=%d mismatches=%d" % (iterations, total_answers, mismatches))
    return 1 if mismatches else 0


if __name__ == "__main__":
    sys.exit(main())

